class Solution:
    def longestDupSubstring(self, s: str) -> str:
        n = len(s)
        if n < 2:
            return ""
        sa = sorted(range(n), key=lambda i: s[i:])
        rank = [0] * n
        for i, x in enumerate(sa):
            rank[x] = i
        best = best_pos = 0
        h = 0
        for i in range(n):
            if rank[i] > 0:
                j = sa[rank[i] - 1]
                while i + h < n and j + h < n and s[i + h] == s[j + h]:
                    h += 1
                if h > best:
                    best, best_pos = h, i
                if h:
                    h -= 1
            else:
                h = 0
        return s[sa[best_pos]:sa[best_pos] + best]

